#!/bin/sh
# =============================================================================
# nrzube — build driver (used by the container and the native builds).
#
#   1. Buildroot       -> target/ + images/ (kernel, dtb)
#   2. U-Boot         -> u-boot.bin (out of tree, pinned commit)
#   3. boot.scr       -> generated by the Buildroot host uboot-tools
#   4. initramfs      -> initrd.img (busybox + the nrzube /init)
#   5. disk image     -> nrzube.img (GPT: boot / slot A / slot B / state)
#   6. manifest       -> release.json + SHA256SUMS
#
# With "boot-gate", only the boot chain is built (Phase 1 validation):
#   the kernel, U-Boot and a stage 1 initramfs that drops to a shell.
#
# usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>
# =============================================================================
set -eu

REPO_DIR="${1:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"
BR2_DIR="${2:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"
OUT_DIR="${3:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"
DIST_DIR="${4:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"
SRC_DIR="${5:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"
TARGET_KIND="${6:?usage: build-all.sh <repo> <br2-dir> <out-dir> <dist-dir> <src-dir> <kind>}"

BR2_EXTERNAL="$REPO_DIR/buildroot"

# The Nix compiler wrapper enables -Werror=format-security, which breaks the
# build of GCC's own libcpp (the "format" hardening flag). It is disabled for
# the build: the flag only makes sense for the final binaries.
if [ -n "${NIX_HARDENING_ENABLE:-}" ]; then
	NIX_HARDENING_ENABLE="$(printf '%s' "$NIX_HARDENING_ENABLE" |
		tr ' ' '\n' | grep -v '^format$' | tr '\n' ' ')"
	export NIX_HARDENING_ENABLE
	echo "nrzube: the Nix 'format' hardening flag is disabled for the build"
fi

# The host binaries built by Buildroot are linked against the system
# libstdc++, which the loader of the Nix glibc does not find by default.
if [ -e /usr/lib/libstdc++.so.6 ]; then
	export LD_LIBRARY_PATH="/usr/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
fi

mkdir -p "$BR2_DIR" "$OUT_DIR" "$DIST_DIR" "$SRC_DIR"

case "$TARGET_KIND" in
boot-gate)
	DEFCONFIG=nrzube_pi5_boot_defconfig
	;;
full)
	DEFCONFIG=nrzube_pi5_defconfig
	;;
*)
	echo "build-all: unknown target '$TARGET_KIND' (boot-gate|full)" >&2
	exit 1
	;;
esac

echo "=== nrzube build ($TARGET_KIND) ==="
echo "repo:     $REPO_DIR"
echo "br2:      $BR2_DIR"
echo "out:      $OUT_DIR"
echo "dist:     $DIST_DIR"

# 0. Buildroot itself (verified against the pinned SHA-256).
# shellcheck disable=SC1091
. "$REPO_DIR/scripts/lib-versions.sh"
"$REPO_DIR/scripts/fetch-buildroot.sh" "$BR2_DIR" "$BUILDROOT_URL" "$BUILDROOT_SHA256"

# 0. Raspberry Pi firmware (GPU firmware and device tree blob).
FIRMWARE_BOOT_DIR="$SRC_DIR/firmware/boot"
"$REPO_DIR/scripts/fetch-firmware.sh" "$SRC_DIR/firmware"
export FIRMWARE_BOOT_DIR

# 1. Rootfs + kernel.
NRZUBE_DEFCONFIG="$DEFCONFIG" "$REPO_DIR/scripts/build-rootfs.sh" "$BR2_DIR" "$BR2_EXTERNAL"

install -m 0644 "$BR2_DIR/output/images/Image" "$OUT_DIR/Image"
install -m 0644 "$BR2_DIR/output/images/bcm2712-rpi-5-b.dtb" "$OUT_DIR/bcm2712-rpi-5-b.dtb"

# 2. U-Boot.
"$REPO_DIR/scripts/build-uboot.sh" "$BR2_DIR/output" "$OUT_DIR" "$SRC_DIR/uboot"

# 3. boot.scr (generated by the Buildroot host uboot-tools).
[ -f "$BR2_DIR/output/images/boot.scr" ] ||
	{ echo "build-all: boot.scr missing" >&2; exit 1; }
install -m 0644 "$BR2_DIR/output/images/boot.scr" "$OUT_DIR/boot.scr"

# The boot script is regenerated on every build: Buildroot only does it when
# the host tools are rebuilt, and the script is part of the source tree.
"$BR2_DIR/output/host/bin/mkimage" -C none -A arm64 -T script \
	-d "$REPO_DIR/buildroot/board/nrzube/boot.cmd" "$OUT_DIR/boot.scr"

if [ "$TARGET_KIND" = "boot-gate" ]; then
	# 4. Stage 1 initramfs (shell only).
	"$REPO_DIR/scripts/build-initramfs-stage1.sh" "$BR2_DIR/output" "$OUT_DIR"

	# 5. The boot gate image.
	"$REPO_DIR/scripts/build-boot-gate-image.sh" "$BR2_DIR/output" "$OUT_DIR" "$DIST_DIR"
else
	# 4. initramfs.
	"$REPO_DIR/scripts/build-initramfs.sh" "$BR2_DIR/output" "$OUT_DIR"

	# 5. Disk image.
	"$REPO_DIR/scripts/build-image.sh" "$BR2_DIR/output" "$OUT_DIR" "$DIST_DIR"
fi

echo "=== nrzube build done ==="
ls -l "$DIST_DIR"
